package com.projectdark.mobile;
import android.content.Context;import android.graphics.*;import com.projectdark.mobile.world.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.json.*;import java.util.*;import java.nio.file.Path;import java.nio.file.Paths;import java.nio.file.Files;import java.io.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class AbelCombatV153Test {
 Context c;
 @Before public void reset(){c=RuntimeEnvironment.getApplication();for(String key:new String[]{"project_dark_f5m_v1","project_dark_skill_book_v1","project_dark_skill_test_v1"})c.getSharedPreferences(key,0).edit().clear().commit();F5mSaveStore.install(c);}
 static final String[] SKILLS={"SK_전사_006","SK_도적_007","SK_마법사_007","SK_성직자_013","SK_무도가_007"};
 String skill(String job){return SKILLS[Arrays.asList(CampaignProgress.JOBS).indexOf(job)];}
 void gear(RuntimeState s,int level){for(String id:new String[]{"IT_B_CAMPAIGN_"+s.rpg().currentJobCode()+"_"+level,"IT_B_CAMPAIGN_TOOL_"+s.rpg().currentJobCode()+"_"+level}){if(s.rpg().inventory().getOrDefault(id,0)==0)assertTrue("normal merchant purchase",TownCommerce.transact(s,TownInteriorDef.Kind.EQUIPMENT,TownCommerce.Operation.BUY,id,1,()->true)==TownCommerce.Result.OK);assertEquals(RpgProgressionState.EquipResult.EQUIPPED,s.rpg().equip(id));}s.applyDerivedGrowth();}
 void learn(RuntimeState s,SkillBook b,String id){SkillAcquisition a=new SkillAcquisition(b);for(int i=0;i<5;i++){SkillAcquisition.Quote q=a.quote(b.get(id),s.rpg());int n=0;while(q.current[i]<q.required[i]&&s.rpg().statPoints()>0&&n++<200){assertTrue(s.rpg().spendStat(SkillAcquisition.STATS[i]));q=a.quote(b.get(id),s.rpg());}}assertTrue(id+" normal learning: "+a.quote(b.get(id),s.rpg()).blockers,a.learn(id,s.rpg()));assertTrue(b.assign(0,id));assertFalse(b.testAccess());}
 void consume(RuntimeState s,String id){if(s.rpg().inventory().getOrDefault(id,0)==0){long price=id.equals("IT_B_MP_POTION")?25:20;assertTrue("potions paid from finite earned Gold",s.rpg().buyItem(id,price));}assertEquals(RpgProgressionState.UseResult.USED,s.rpg().useConsumable(id,s));}
 int potions;float seconds;int casts;
 void frame(RuntimeState s,RuntimeCombatSession combat,MonsterAIController ai,WorldRuntimeAdapter world,SkillBook b){RuntimeCombatSession.FrameResult result=combat.tick(.05f);for(CombatResolver.Event e:result.events)if(e.type==CombatResolver.EventType.EFFECT_APPLIED&&e.actorId.equals("player"))b.practiced(e.actionId);s.tick(.05f);s.applyDerivedGrowth();ai.tick(s,.05f);if(world!=null){if(s.skillEffects().rooted("player"))world.cancelForAction();else world.tickNavigation(.05f);}seconds+=.05f;if(s.player().alive&&s.player().hp<s.player().maxHp*.65f){consume(s,RpgProgressionState.B_SMALL_POTION_ITEM_ID);potions++;}if(s.player().alive&&s.player().mp<s.player().maxMp*.2f){consume(s,"IT_B_MP_POTION");potions++;}assertTrue("normal build survives active monster AI",s.player().alive);}
 void hunt(RuntimeState s,RuntimeCombatSession combat,MonsterAIController ai,SkillBook b,RuntimeState.Monster target){
  WorldRuntimeAdapter world=CampaignNavigationTest.adapter(s);WorldMoveTargetController.Snapshot path=world.requestMonsterApproach(target.id,CanonicalMeleeTileContract.REACH_DISTANCE);assertTrue(path.status!=WorldMoveTargetController.Status.BLOCKED);int frames=0;float before=seconds;
  while(target.alive&&frames++<5000){
   if(!world.presentationMoving()&&CanonicalMeleeTileContract.reachable(s.player().x,s.player().y,target.x,target.y)){
    String id=skill(s.rpg().currentJobCode());CombatActionOrchestrator.Submission cast=combat.submitPlayer(target.id,id);if(cast.accepted())casts++;else combat.submitPlayerBasicAttack(target.id);
   }else if(!world.presentationMoving())world.requestMonsterApproach(target.id,CanonicalMeleeTileContract.REACH_DISTANCE);
   frame(s,combat,ai,world,b);
  }assertFalse("real attack defeats "+target.id,target.alive);assertTrue("bounded fight including live navigation",seconds-before<250);
 }
 @Test public void profilesBindEverySpeciesAndSourceRewardsRemainSeparate()throws Exception{
  Set<String> found=new HashSet<>();for(String map:AbelCoastGeometry.ROUTE)for(RuntimeState.Monster m:AbelCoastMonsters.spawn(map)){AbelCombatProfile p=AbelCombatProfile.forId(m.id);assertNotNull(p);assertEquals(p.hp,m.maxHp);assertEquals(p.level,m.level);assertEquals(p.mp,m.mp);assertEquals(p.exp,new AdaptedCampaignRewardCatalog().find(p.id).exp);found.add(p.id);}assertEquals(new HashSet<>(AbelCoastMonsters.ALL),found);assertEquals(13,found.size());assertTrue(new CanonicalMonsterRewardCatalog().find("ABEL_BERSERKER").exp>500000);assertEquals(70,AbelCombatProfile.forId("ABEL_KINGARK").level);assertTrue(AbelCombatProfile.forId("ABEL_GRAB").ac<AbelCombatProfile.forId("ABEL_PONG").ac);
 }
 @Test public void actualGameViewShowsMonsterCastParticlesAndLevelWithoutTestAccess()throws Exception{
  GameView view=new GameView(c);view.layout(0,0,960,540);RuntimeState s=TownInteriorTest.field(view,"state");AbelCoastV139Test.restoreD04(s.rpg(),"WARRIOR");AbelTownV152Test access=new AbelTownV152Test();access.call(view,"enterPoteField");access.call(view,"changeCampaignMap",new Class<?>[]{String.class,boolean.class},"MAP_ABEL_COAST_1B",false);RuntimeState.Monster caster=s.monsters().stream().filter(m->m.campaignRewardProfileId.equals("ABEL_ARKPUS")).findFirst().get();for(RuntimeState.Monster m:s.monsters())if(m!=caster){m.alive=false;m.hp=0;m.respawnClock=1000;}
  WorldRuntimeAdapter w=TownInteriorTest.field(view,"poteFieldAdapter");boolean placed=false;for(WorldMoveTargetController.TileCenter t:w.navigationTiles())if(Math.hypot(t.x-caster.x,t.y-caster.y)>65&&Math.hypot(t.x-caster.x,t.y-caster.y)<100&&w.canPlayerOccupy(t.x,t.y)){s.player().x=t.x;s.player().y=t.y;placed=true;break;}assertTrue(placed);w.cancelForAction();w.snapCameraToPlayer();s.applyDerivedGrowth();s.player().hp=s.player().maxHp;int hp=s.player().hp,mp=caster.mp;TownInteriorTest.tick(view,7);assertTrue(caster.mp<mp);AbelSpellRenderer fx=TownInteriorTest.field(view,"abelSpellFx");assertFalse(((List<?>)TownInteriorTest.field(fx,"shots")).isEmpty());Bitmap b=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888);view.draw(new Canvas(b));Path p=Paths.get("build/reports/abel-v153/actual-monster-magic.png");Files.createDirectories(p.getParent());try(OutputStream out=Files.newOutputStream(p)){assertTrue(b.compress(Bitmap.CompressFormat.PNG,100,out));}TownInteriorTest.tick(view,12);assertTrue(s.player().hp<hp);SkillBook book=TownInteriorTest.field(view,"skillBook");assertFalse(book.testAccess());
 }
 @Test public void magicUsesRealWindupMpLosControlAndSavedStatusAndBossRecoversOnlyOnce()throws Exception{
  RuntimeState s=new RuntimeState();AbelCoastV139Test.restoreD04(s.rpg(),"WARRIOR");s.enterCampaignMap("MAP_ABEL_COAST_1B",false);RuntimeState.Monster caster=s.monsters().stream().filter(m->m.campaignRewardProfileId.equals("ABEL_ARKPUS")).findFirst().get();s.player().x=caster.x-64;s.player().y=caster.y-32;RuntimeCombatSession combat=new RuntimeCombatSession(s,(a,t)->true,(a,id)->false,a->true);MonsterAIController ai=new MonsterAIController(new MonsterAIController.SharedResolverAttackRouter(combat.monsterAutoBridge()));for(RuntimeState.Monster m:s.monsters())if(m!=caster){m.alive=false;m.hp=0;m.respawnClock=1000;}int hp=s.player().hp,mp=caster.mp;ai.tick(s,.05f);assertEquals(MonsterAIController.SubmissionOutcome.ACCEPTED,ai.lastAttackSubmission().outcome);assertEquals("MONSTER_WATER",ai.lastAttackSubmission().actionId);assertEquals(mp-8,caster.mp);combat.tick(.3f);assertEquals(hp,s.player().hp);combat.tick(.4f);assertTrue(s.player().hp<hp);
  RuntimeCombatSession blocked=new RuntimeCombatSession(s,(a,t)->false,(a,id)->false,a->true);assertFalse(blocked.monsterAutoBridge().submit(caster.id,"player","MONSTER_WATER").outcome==MonsterAutoCombatBridge.Outcome.ACCEPTED);caster.mp=0;assertFalse(combat.monsterAutoBridge().submit(caster.id,"player","MONSTER_FIRE").outcome==MonsterAutoCombatBridge.Outcome.ACCEPTED);
  s.skillEffects().put("player","MONSTER_VENOM","POISON",2,5);SkillEffectState restored=new SkillEffectState();assertTrue(restored.restore(s.skillEffects().snapshot()));assertTrue(restored.has("player","POISON"));
  s.enterCampaignMap("MAP_ABEL_COAST_4C",false);RuntimeState.Monster king=s.monsters().stream().filter(m->m.campaignRewardProfileId.equals("ABEL_KINGARK")).findFirst().get();for(RuntimeState.Monster m:s.monsters())if(m!=king){m.alive=false;m.hp=0;m.respawnClock=1000;}s.applyDerivedGrowth();s.player().hp=s.player().maxHp;king.hp=king.maxHp/4;int low=king.hp;s.player().x=king.x-32;s.player().y=king.y-16;combat=new RuntimeCombatSession(s,(a,t)->true,(a,id)->false,a->true);ai=new MonsterAIController(new MonsterAIController.SharedResolverAttackRouter(combat.monsterAutoBridge()));
  for(int i=0;i<100&&!king.bossRecovered;i++){combat.tick(.05f);s.tick(.05f);ai.tick(s,.05f);}assertTrue("boss retreats then resolves one heal",king.bossRecovered);assertEquals(low+king.maxHp/8,king.hp);assertTrue(Math.hypot(king.x-king.spawnX,king.y-king.spawnY)>0);int healed=king.hp;for(int i=0;i<200;i++){combat.tick(.05f);s.tick(.05f);ai.tick(s,.05f);}assertEquals("no endless boss heal",healed,king.hp);
  F5mSaveStore.bindRuntime(s,F5mAdaptedPrologueQuest.openingFixture(),new GrowthQuest2());assertTrue(F5mSaveStore.checkpointActive());RuntimeState next=new RuntimeState();next.enterCampaignMap("MAP_ABEL_COAST_4C",false);F5mSaveStore.restoreRuntimeActive(next);RuntimeState.Monster copy=next.monsters().stream().filter(m->m.id.equals(king.id)).findFirst().get();assertTrue(copy.bossRecovered);assertEquals(king.hp,copy.hp);assertEquals(king.mp,copy.mp);
 }
 @Test public void allFiveNormalJobsUsePaidEquipmentLearnedSkillsAndConsecutiveLiveAiHuntsToLevel70()throws Exception{
  JSONObject report=new JSONObject();for(String job:CampaignProgress.JOBS){reset();potions=casts=0;seconds=0;RuntimeState s=new RuntimeState();AbelCoastV139Test.restoreD04(s.rpg(),job);SkillBook b=SkillBook.load(c);b.bindJob(s.rpg()::currentJobCode);gear(s,41);learn(s,b,skill(job));s.applyDerivedGrowth();s.player().hp=s.player().maxHp;s.player().mp=s.player().maxMp; // one initial safe-point rest only
   final WorldRuntimeAdapter[] los={null};RuntimeCombatSession combat=new RuntimeCombatSession(s,(a,t)->los[0]==null||los[0].hasCombatLineOfSight(a,t),(a,id)->b.usable(id),a->true);combat.setSkillProficiency(b::proficiency);combat.setBasicHits(b::basicHits);MonsterAIController ai=new MonsterAIController(new MonsterAIController.SharedResolverAttackRouter(combat.monsterAutoBridge()));int kills=0;Map<Integer,Integer> population=new HashMap<>();
   F5mSaveStore.bindRuntime(s,F5mAdaptedPrologueQuest.openingFixture(),new GrowthQuest2());F5mSaveStore.restoreAndBindSkillsActive(b);
   for(int n=1;n<=18;n++){CampaignProgress.Def d=s.rpg().campaign().next(s.rpg());assertEquals(String.format(Locale.ROOT,"E%02d",n),d.id);CampaignProgressTest.enter(s,d.map);los[0]=CampaignNavigationTest.adapter(s);if(n==10||n==15){gear(s,n==10?56:65);}assertTrue(job+" accepts "+d.id,s.rpg().campaign().accept(d.id,s.rpg(),b));int waits=0;
    while(s.rpg().campaign().status(d,s.rpg())!=CampaignProgress.Status.REPORT){RuntimeState.Monster target=null;float best=Float.MAX_VALUE;for(RuntimeState.Monster m:s.monsters())if(m.alive&&s.rpg().campaign().wanted(d,m.campaignRewardProfileId)){float dist=(float)Math.hypot(m.x-s.player().x,m.y-s.player().y);if(dist<best){target=m;best=dist;}}if(target==null){assertTrue(waits++<1500);frame(s,combat,ai,null,b);continue;}population.put(n,s.monsters().size());hunt(s,combat,ai,b,target);kills++;}
    assertTrue(s.rpg().campaign().claim(d.id,s.rpg()));assertFalse(s.rpg().campaign().claim(d.id,s.rpg()));assertTrue(F5mSaveStore.checkpointActive());
   }
   assertTrue(s.rpg().normalLevel()>=70);assertTrue(s.rpg().campaign().finished());assertNull(s.rpg().campaign().next(s.rpg()));assertFalse(b.testAccess());assertTrue(casts>0);assertTrue(kills>80);assertTrue(s.rpg().gold()>0);RpgProgressionState copy=new RpgProgressionState();F5mSaveStore.restoreRewardsActive(copy);assertEquals(CampaignProgress.earnedExp(s.rpg()),CampaignProgress.earnedExp(copy));assertEquals(s.rpg().inventory(),copy.inventory());report.put(job,new JSONObject().put("level",s.rpg().normalLevel()).put("kills",kills).put("combatAndNavigationSeconds",seconds).put("skillCasts",casts).put("consumedPaidPotions",potions).put("gold",s.rpg().gold()).put("skill",skill(job)).put("proficiency",b.proficiency(skill(job))).put("scope","Normal stat allocation, paid gear/learning/potions, full original population and live AI/LOS/path/Resolver. One initial safe-point rest, no per-kill rest or damage injection. Quest milestone EXP included; host simulation, not phone acceptance."));
  }Path p=Paths.get("build/reports/abel-v153/five-jobs-level70.json");Files.createDirectories(p.getParent());Files.writeString(p,report.toString(2));
 }
}
